{"cmd":"python - <<'PY'
import json
import re
import whisper

INPUT_VIDEO = "/root/input.mp4"
ANNOTATIONS = "/root/annotations.json"

FILLER_SINGLE = {
    "um", "uh", "hum", "hmm", "mhm",
    "like", "yeah", "so", "well", "okay", "basically",
}
FILLER_PHRASES = {
    "you know",
    "i mean",
    "kind of",
    "i guess",
}


def clean_token(token: str) -> str:
    return re.sub(r"[^A-Za-z0-9]+", "", token.lower())


def normalize_single(clean: str) -> str:
    if not clean:
        return ""
    if clean == "ok":
        return "okay"
    if clean in {"uh", "um", "hum", "hmm", "mhm", "like", "yeah", "so", "well", "okay", "basically"}:
        return clean
    if re.fullmatch(r"u+h+", clean):
        return "uh"
    if re.fullmatch(r"u+m+", clean):
        return "um"
    if re.fullmatch(r"h+u+m+", clean):
        return "hum"
    if re.fullmatch(r"h+m+", clean):
        return "hmm"
    if re.fullmatch(r"m+h+m+", clean):
        return "mhm"
    if clean == "okey":
        return "okay"
    return clean


def find_phrases(tokens):
    matches = []
    n = len(tokens)
    for i in range(n - 1):
        w1 = tokens[i]["clean"]
        w2 = tokens[i + 1]["clean"]
        if w1 == "you" and w2 == "know":
            matches.append({"word": "you know", "timestamp": tokens[i]["start"]})
        if w1 == "i" and w2 == "mean":
            matches.append({"word": "i mean", "timestamp": tokens[i]["start"]})
        if w1 == "kind" and w2 == "of":
            matches.append({"word": "kind of", "timestamp": tokens[i]["start"]})
        if w1 == "i" and w2 == "guess":
            matches.append({"word": "i guess", "timestamp": tokens[i]["start"]})
    for t in tokens:
        w = t["clean"]
        if w == "kinda":
            matches.append({"word": "kind of", "timestamp": t["start"]})
        if w == "youknow":
            matches.append({"word": "you know", "timestamp": t["start"]})
        if w == "imean":
            matches.append({"word": "i mean", "timestamp": t["start"]})
        if w == "iguess":
            matches.append({"word": "i guess", "timestamp": t["start"]})
    return matches

print("Loading Whisper model (tiny.en)...")
model = whisper.load_model("tiny.en")

print("Transcribing with word timestamps...")
result = model.transcribe(
    INPUT_VIDEO,
    word_timestamps=True,
    language="en",
    fp16=False,
    beam_size=1,
    best_of=1,
    temperature=0,
    condition_on_previous_text=False,
)

words = []
for segment in result.get("segments", []):
    for w in segment.get("words", []):
        clean = clean_token(w.get("word", ""))
        if not clean:
            continue
        words.append({
            "word": w.get("word", ""),
            "clean": clean,
            "start": float(w.get("start", 0.0)),
            "end": float(w.get("end", 0.0)),
        })

matches = []
for t in words:
    norm = normalize_single(t["clean"])
    if norm in FILLER_SINGLE:
        matches.append({"word": norm, "timestamp": t["start"]})

matches.extend(find_phrases(words))

filtered = []
for m in matches:
    w = m["word"].lower().strip()
    if w in FILLER_SINGLE or w in FILLER_PHRASES:
        filtered.append({"word": w, "timestamp": round(float(m["timestamp"]), 2)})

seen = set()
final = []
for m in sorted(filtered, key=lambda x: x["timestamp"]):
    key = (m["word"], m["timestamp"])
    if key in seen:
        continue
    seen.add(key)
    final.append(m)

with open(ANNOTATIONS, "w") as f:
    json.dump(final, f, indent=2)

print(f"Wrote {len(final)} annotations -> {ANNOTATIONS}")
